import React, { useState } from 'react';

export default function ThresholdPanel() {
  const [thresholds, setThresholds] = useState({
    pre: '10 Minutes',
    post: '10 Minutes',
    segment: '10 Minutes',
    confidence: '0.50'
  });

  const rows = [
    { label: 'Pre-Event Recording',  key: 'pre' },
    { label: 'Post-Event Recording', key: 'post' },
    { label: 'Segment Duration',     key: 'segment' },
    { label: 'Confidence Threshold', key: 'confidence' },
  ];

  return (
    <div style={{ borderBottom: '1px solid #1e2d47', padding: '10px 12px', flexShrink: 0 }}>
      <div style={{ fontSize: 11, fontWeight: 700, color: '#94a3b8', textTransform: 'uppercase', letterSpacing: '.5px', marginBottom: 8 }}>
        Recording & Thresholds
      </div>

      {rows.map((r, i) => (
        <div key={i} style={{
          display: 'flex', justifyContent: 'space-between', alignItems: 'center',
          padding: '5px 0', borderBottom: '1px solid #1e2d47'
        }}>
          <span style={{ fontSize: 11, color: '#94a3b8' }}>{r.label}</span>
          <span style={{ fontSize: 11, fontWeight: 600, color: '#fff', display: 'flex', alignItems: 'center', gap: 6 }}>
            {thresholds[r.key]}
            <span style={{ fontSize: 11, color: '#64748b', cursor: 'pointer' }}>✏️</span>
          </span>
        </div>
      ))}

      <button
        onClick={() => alert('Settings saved!')}
        style={{
          background: '#3b82f6', color: '#fff', border: 'none',
          width: '100%', padding: '7px', borderRadius: 6,
          fontSize: 11, fontWeight: 700, cursor: 'pointer', marginTop: 8
        }}
      >
        Save Settings
      </button>
    </div>
  );
}
